+          ~in_closure=?,
+          ~call_stack: CallStack.state,
+          // Inputs
+          ~reuse_map: IncrEval.reuse_map,
+          env,
+          exp: DHExp.t,
+          // Outputs
+          ~parent_state: ref(EvaluatorState.t),
+          ~outbox: option(ref(IncrEval.outbox(EvaluatorState.t))),
+          ~current_top_id: option(Id.t),
+        )
