+      (~reuse_map, ~in_closure=?, ~call_stack, ~state, env, exp: DHExp.t) => {
+    let.trampoline (is_finished, effects, next) =
+      eval_0_main(~reuse_map, ~in_closure?, ~call_stack, ~state, env, exp);
