+          probe_call_stack,
+          expr_id,
+          original_call_stack.stack,
+        );
+      let sample =
+        Sample.mk(
+          ~args,
+          ~step_start,
+          ~step_end,
+          expr_id,
+          final_value,
+          env,
+          original_call_stack.stack,
+          probe,
+        );
+      state := EvaluatorState.add_sample(state^, sample);
+      update_outbox_current(state^);
+    | None => ()
+    };
