+      // Record incremental entry if required
+      let info_snapshot =
+        if (call_stack.stack != []) {
+          None;
+        } else {
+          EvalInfo.find_opt(expr_id, eval_info);
+        };
+      switch (info_snapshot) {
+      | None => Trampoline.return(final_value)
+      | Some({
+          elab_term: prev_elab,
+          co_ctx,
+          probe_targets: prev_probe_targets,
+          _,
+        }) =>
+        let entry: IncrEval.entry(EvaluatorState.t) = {
+          prev_elab,
+          prev_reuse_map:
