+type yielding_evaluation = {
+  env: Environment.t(Exp.t),
+  state: ref(EvaluatorState.t),
+  outbox: ref(IncrEval.outbox(EvaluatorState.t)),
+  continuation: Trampoline.Yielding.continuation(DHExp.t),
