+let start_yielding_evaluation =
+    (
+      ~prev: EvaluatorState.incr_eval=IncrEval.empty,
+      ~eval_info: EvalInfo.t=EvalInfo.empty,
+      ~env,
+      ~reuse_map: option(IncrEval.reuse_map)=?,
+      d: DHExp.t,
+    )
