+open Util;
+
+[@deriving (show({with_path: false}), sexp, yojson)]
+type term =
+  | Closure([@show.opaque] Environment.t(Exp.t), t)
+  | Filter(TermBase.StepperFilterKind.t, t)
+  | Seq1(t, DHExp.t)
+  | Seq2(DHExp.t, t)
+  | Let1(Pat.t, t, DHExp.t)
+  | Let2(Pat.t, DHExp.t, t)
+  | Theorem(Pat.t, DHExp.t, t)
+  | Fun(Pat.t, t, option(Typ.t), option(Var.t))
+  | FixF(Pat.t, t, option(Environment.t(Exp.t)))
+  | TypAp(t, Typ.t)
+  | Ap1(Operators.ap_direction, t, DHExp.t)
+  | Ap2(Operators.ap_direction, DHExp.t, t)
+  | DeferredAp1(t, list(DHExp.t))
+  | DeferredAp2(DHExp.t, t, (list(DHExp.t), list(DHExp.t)))
+  | If1(t, DHExp.t, DHExp.t)
+  | If2(DHExp.t, t, DHExp.t)
+  | If3(DHExp.t, DHExp.t, t)
+  | UnOp(Operators.op_un, t)
+  | BinOp1(Operators.op_bin, t, DHExp.t)
+  | BinOp2(Operators.op_bin, DHExp.t, t)
+  | TupleExtension1(t, DHExp.t)
+  | TupleExtension2(DHExp.t, t)
+  | TupLabel(DHExp.t, t)
+  | Tuple(t, (list(DHExp.t), list(DHExp.t)))
+  | Dot1(t, DHExp.t)
+  | Dot2(DHExp.t, t)
+  | Test(t)
+  | HintedTest(t, DHExp.t)
+  | Parens(t)
+  | ListLit(t, (list(DHExp.t), list(DHExp.t)))
+  | MultiHole(t, (list(Any.t), list(Any.t)))
+  | Cons1(t, DHExp.t)
+  | Cons2(DHExp.t, t)
+  | ListConcat1(t, DHExp.t)
+  | ListConcat2(DHExp.t, t)
+  | Asc(t, Typ.t)
+  | DynamicErrorHole(t, InvalidOperationError.t)
+  | MatchScrut(t, list((Pat.t, DHExp.t)))
+  | MatchRule(
+      DHExp.t,
+      Pat.t,
+      t,
+      (list((Pat.t, DHExp.t)), list((Pat.t, DHExp.t))),
+    )
+and t =
+  | Mark
+  | Term({
+      term,
+      ids: list(Id.t),
+    });
+
+let rec compose = (ctx: t, d: DHExp.t): DHExp.t => {
+  switch (ctx) {
+  | Mark => d
+  | Term({term, ids}) =>
+    let wrap = DHExp.mk(ids);
+    switch (term) {
+    | Closure(env, ctx) =>
+      let d = compose(ctx, d);
+      Closure(env, d) |> wrap;
+    | Filter(flt, ctx) =>
+      let d = compose(ctx, d);
+      Filter(flt, d) |> wrap;
+    | Seq1(ctx, d2) =>
+      let d1 = compose(ctx, d);
+      Seq(d1, d2) |> wrap;
+    | Seq2(d1, ctx) =>
+      let d2 = compose(ctx, d);
+      Seq(d1, d2) |> wrap;
+    | Ap1(dir, ctx, d2) =>
+      let d1 = compose(ctx, d);
+      Ap(dir, d1, d2) |> wrap;
+    | Ap2(dir, d1, ctx) =>
+      let d2 = compose(ctx, d);
+      Ap(dir, d1, d2) |> wrap;
+    | DeferredAp1(ctx, d2s) =>
+      let d1 = compose(ctx, d);
+      DeferredAp(d1, d2s) |> wrap;
+    | DeferredAp2(d1, ctx, (ld, rd)) =>
+      let d2 = compose(ctx, d);
+      DeferredAp(d1, ListUtil.rev_concat(ld, [d2, ...rd])) |> wrap;
+    | If1(ctx, d2, d3) =>
+      let d' = compose(ctx, d);
+      If(d', d2, d3) |> wrap;
+    | If2(d1, ctx, d3) =>
+      let d' = compose(ctx, d);
+      If(d1, d', d3) |> wrap;
+    | If3(d1, d2, ctx) =>
+      let d' = compose(ctx, d);
+      If(d1, d2, d') |> wrap;
+    | Test(ctx) =>
+      let d1 = compose(ctx, d);
+      Test(d1) |> wrap;
+    | HintedTest(ctx, h) =>
+      let d1 = compose(ctx, d);
+      HintedTest(d1, h) |> wrap;
+    | Parens(ctx) =>
+      let d1 = compose(ctx, d);
+      Parens(d1) |> wrap;
+    | UnOp(op, ctx) =>
+      let d1 = compose(ctx, d);
+      UnOp(op, d1) |> wrap;
+    | BinOp1(op, ctx, d2) =>
+      let d1 = compose(ctx, d);
+      BinOp(op, d1, d2) |> wrap;
+    | BinOp2(op, d1, ctx) =>
+      let d2 = compose(ctx, d);
+      BinOp(op, d1, d2) |> wrap;
+    | TupleExtension1(ctx, d2) =>
+      let d1 = compose(ctx, d);
+      TupleExtension(d1, d2) |> wrap;
+    | TupleExtension2(d1, ctx) =>
+      let d2 = compose(ctx, d);
+      TupleExtension(d1, d2) |> wrap;
+    | Cons1(ctx, d2) =>
+      let d1 = compose(ctx, d);
+      Cons(d1, d2) |> wrap;
+    | Cons2(d1, ctx) =>
+      let d2 = compose(ctx, d);
+      Cons(d1, d2) |> wrap;
+    | ListConcat1(ctx, d2) =>
+      let d1 = compose(ctx, d);
+      ListConcat(d1, d2) |> wrap;
+    | ListConcat2(d1, ctx) =>
+      let d2 = compose(ctx, d);
+      ListConcat(d1, d2) |> wrap;
+    | TupLabel(label, ctx) =>
+      let d = compose(ctx, d);
+      TupLabel(label, d) |> wrap;
+    | Dot1(ctx, d2) =>
+      let d1 = compose(ctx, d);
+      Dot(d1, d2) |> wrap;
+    | Dot2(d1, ctx) =>
+      let d2 = compose(ctx, d);
+      Dot(d1, d2) |> wrap;
+    | Tuple(ctx, (ld, rd)) =>
+      let d = compose(ctx, d);
+      Tuple(ListUtil.rev_concat(ld, [d, ...rd])) |> wrap;
+    | ListLit(ctx, (ld, rd)) =>
+      let d = compose(ctx, d);
+      ListLit(ListUtil.rev_concat(ld, [d, ...rd])) |> wrap;
+    | MultiHole(ctx, (ld, rd)) =>
+      let d = compose(ctx, d);
+      MultiHole(ListUtil.rev_concat(ld, [Exp(d), ...rd])) |> wrap;
+    | Let1(dp, ctx, d2) =>
+      let d = compose(ctx, d);
+      Let(dp, d, d2) |> wrap;
+    | Let2(dp, d1, ctx) =>
+      let d = compose(ctx, d);
+      Let(dp, d1, d) |> wrap;
+    | Theorem(dp, d1, ctx) =>
+      let d = compose(ctx, d);
+      Theorem(dp, d1, d) |> wrap;
+    | Fun(dp, ctx, typ, v) =>
+      let d = compose(ctx, d);
+      Fun(dp, d, typ, v) |> wrap;
+    | FixF(v, ctx, env) =>
+      let d = compose(ctx, d);
+      FixF(v, d, env) |> wrap;
+    | Asc(ctx, ty1) =>
+      let d = compose(ctx, d);
+      Asc(d, ty1) |> wrap;
+    | DynamicErrorHole(ctx, err) =>
+      let d = compose(ctx, d);
+      DynamicErrorHole(d, err) |> wrap;
+    | MatchScrut(ctx, rules) =>
+      let d = compose(ctx, d);
+      Match(d, rules) |> wrap;
+    | MatchRule(scr, p, ctx, (lr, rr)) =>
+      let d = compose(ctx, d);
+      Match(scr, ListUtil.rev_concat(lr, [(p, d), ...rr])) |> wrap;
+    | TypAp(ctx, ty) =>
+      let d = compose(ctx, d);
+      TypAp(d, ty) |> wrap;
+    };
+  };
+};

