+open Util;
+open Transition;
+
+module EvalObj = {
+  [@deriving (show({with_path: false}), sexp, yojson)]
+  type t = {
+    env: Environment.t(Exp.t), // technically can be calculated from ctx
+    d_loc: DHExp.t,
+    ctx: EvalCtx.t,
+    knd: step_kind,
+  };
+
+  let mk = (ctx, env, d_loc, knd) => {
+    ctx,
+    env,
+    d_loc,
+    knd,
+  };
+
+  let wrap = (f: EvalCtx.t => EvalCtx.t, obj: t) => {
+    ...obj,
+    ctx: obj.ctx |> f,
+  };
+
+  [@deriving (show({with_path: false}), sexp, yojson)]
+  type persistent = {
+    exp_idx: int, // The index of the expression being stepped
+    at_exp: Exp.t // The expression being stepped
+  };
+
+  let persist = (obj: t): persistent => {
+    let full_exp = EvalCtx.compose(obj.ctx, obj.d_loc);
+    {
+      exp_idx: ProofHacks.exp_idx(obj.d_loc, full_exp),
+      at_exp: obj.d_loc,
+    };
+  };
+};
+
+let rec matches =
+        (
+          env: Environment.t(Exp.t),
+          flt: FilterEnvironment.t,
+          ctx: EvalCtx.t,
+          exp: DHExp.t,
+          act: FilterAction.t,
+          idx: int,
+        )
+        : (FilterAction.t, int, EvalCtx.t) => {
+  let composed = EvalCtx.compose(ctx, exp);
+  let (pact, pidx) = (act, idx);
+  let (mact, midx) = FilterMatcher.matches(~env, ~exp=composed, ~act, flt);
+  let (act, idx) =
+    switch (ctx) {
+    | Term({term: Filter(_, _), _}) => (pact, pidx)
+    | _ => midx > pidx ? (mact, midx) : (pact, pidx)
+    };
+  let map = ((a, i, c), f) => {
+    (a, i, f(c));
+  };
+  let (let+) = map;
+  let (ract, ridx, rctx) =
+    switch (ctx) {
+    | Mark => (act, idx, EvalCtx.Mark)
+    | Term({term, ids}) =>
+      let rewrap = term =>
+        EvalCtx.Term({
+          term,
+          ids,
+        });
+      switch ((term: EvalCtx.term)) {
+      | Closure(env, ctx) =>
+        let+ ctx = matches(env, flt, ctx, exp, act, idx);
+        Closure(env, ctx) |> rewrap;
