+         * ASCII ones they cannot be a prefix of a keyword. */
+        frequency([
+          (4, string_size(~gen=char_range('a', 'z'), int_range(1, 1))),
+          (1, oneofl(nonascii_name_chars)),
+        ]);
+      }
+    );
