+  QCheck.Gen.(
+    let* list_size = n <= 1 ? pure(0) : int_range(2, n);
+    switch (list_size) {
+    | 0 => pure([||])
+    | _ => nat_split(~size=list_size, n - list_size)
+    }
+  );
