+%{
+open AST
+%}
+
+
+
+%token T_TYP
+%token P_PAT
+%token TP_TPAT
+%token E_EXP
+%token TILDE
+%token NAMED_FUN
+%token POLY
+%token REC
+%token UNDEF
+%token <string> PROJECTOR_INVOKE
+%token <string> LIVELIT_IDENT
+%token MOD_SEMI
+%token TYP
+%token TYP_FUN
+%token FIX
+%token WILD
+%token QUESTION
+%token AT_SYMBOL
+%token TYP_AP_SYMBOL
+%token CONS
+%token TEST
+%token HINT
+%token PAUSE
+%token DEBUG
+%token HIDE
+%token EVAL
+%token <string> IDENT
+%token <string> CONSTRUCTOR_IDENT
+%token <string> STRING
+%token <string> QUOTED_LABEL
+%token TRUE 
+%token FALSE
+%token <Util.Bigint.t> INT
+%token <float> FLOAT
+%token LET
+%token USE
+%token MODULE
+%token FUN
+%token CASE
+%token OPEN_SQUARE_BRACKET
+%token CLOSE_SQUARE_BRACKET
+%token OPEN_PAREN
+%token CLOSE_PAREN
+%token OPEN_TRIPLE_CURLY
+%token CLOSE_TRIPLE_CURLY
+%token OPEN_CURLY
+%token CLOSE_CURLY
+%token DASH_ARROW
+%token EQUAL_ARROW
+%token SINGLE_EQUAL
+%token TURNSTILE
+%token TUPLE_EXTENSION
+%token DOT
+
+(* Poly ops *)
+%token DOUBLE_EQUAL
+%token NOT_EQUAL
+
+(* String ops *)
+%token STRING_CONCAT
+
+(* Int ops *)
+%token PLUS
+%token MINUS
+%token POWER
+%token TIMES
+%token DIVIDE
+%token LESS_THAN
+%token PIPELINE
+%token LESS_THAN_EQUAL
+%token GREATER_THAN
+%token GREATER_THAN_EQUAL
+(* Float ops *)
+%token DOUBLE_EQUAL_FLOAT
+%token NOT_EQUAL_FLOAT
+%token PLUS_FLOAT
+%token MINUS_FLOAT
+%token DIVIDE_FLOAT
+%token POWER_FLOAT
+%token TIMES_FLOAT
+%token LESS_THAN_FLOAT
+%token LESS_THAN_EQUAL_FLOAT
+%token GREATER_THAN_FLOAT
+%token GREATER_THAN_EQUAL_FLOAT
+(*logical ops*)
+%token L_AND
+%token L_OR
+%token L_NOT
+(*bitwise ops*)
+%token COMMA
+%token COLON
+%token EOF
+%token IN
+%token UNIT
+%token END
+
+(* type tokens *)
+%token INT_TYPE
+%token SINT_TYPE
+%token NAT_TYPE
+%token FLOAT_TYPE
+%token BOOL_TYPE
+%token STRING_TYPE
+%token VOID_TYPE
+%token UNKNOWN
+%token INTERNAL
+
+%token IF
+%token THEN
+%token ELSE
+
+%token SEMI_COLON
+
+
+
+(* Precedences *)
+
+
+
+/* Structural mixfix forms - loosest binding (bodies include flat sequences) */
+%nonassoc LET_EXP
+%right SUM_TYP
+%right DASH_ARROW
+%nonassoc IF_EXP
+
+/* Flat sequences - tighter than structural forms */
+%right SEMI_COLON
+
+/* Module item expression reduction: higher than SEMI_COLON so that inside
+   module bodies, the parser reduces exp to modItemExp rather than shifting
+   ';' for Seq. This only affects the modItemExp production. */
+%nonassoc MOD_ITEM_EXP
+
+%right L_OR
+%right L_AND
+
+
