+[@deriving (show({with_path: false}), yojson)]
+type key =
+  | D(string)
+  | U(string);
+
+[@deriving (show({with_path: false}), yojson)]
+type sys =
+  | Mac
+  | PC;
+
+[@deriving (show({with_path: false}), yojson)]
+type held =
+  | Down
+  | Up;
+
+[@deriving (show({with_path: false}), yojson)]
+type t = {
