+  include M;
+  let map = (x, f) => bind(x, a => M.return(f(a)));
+};
+
+module type MONAD_ZIP = {
+  include MONAD_FUNCTOR;
+  let zip: (t('a), t('b)) => t(('a, 'b));
+};
+
