+module type STATE = {
+  type t;
+};
+
+module type S = {
+  type state;
+
+  include Monads.MONAD with type t('a) = state => (state, 'a);
+
+  let get: t(state);
+  let put: state => t(unit);
+  let modify: (state => state) => t(unit);
+  let modify': (state => ('a, state)) => t('a);
+};
+
+module Make = (ST: STATE) => {
+  type state = ST.t;
+
+  module T = {
+    [@deriving sexp]
+    type t('a) = state => (state, 'a);
+
+    let return = (x, s) => (s, x);
+
+    let bind = (xf, f, s) => {
+      let (s', x) =
+        switch (xf(s)) {
+        | r => r
+        | exception exn =>
+          print_endline(
+            "bind exception: "
+            ++ Sexplib.Sexp.to_string_hum(Sexplib.Std.sexp_of_exn(exn)),
+          );
+          raise(exn);
+        };
+      f(x, s');
+    };
+
+    let get = s => (s, s);
+
+    let put = (x, _) => (x, ());
+
+    let modify = f => bind(get, s => put(f(s)));
+
+    let modify' = f =>
+      bind(
+        get,
+        s => {
+          let (x, s) = f(s);
+          bind(put(s), _ => return(x));
+        },
+      );
+  };
+
+  include T;
+  include Monads.Make_Monad_B(T);
+};

